class Library{static async init(){await Common.loadJs("CustomGlide.min.js"),await CustomGlide.initAll();var e=document.querySelector(".boxLibrary:not(.boxLibraryInited) .glideBig");let l=document.querySelector(".boxLibrary:not(.boxLibraryInited) .glideThumb");if(e&&l){e.closest(".boxLibrary").classList.add("boxLibraryInited");let i=CustomGlide.getInstance(e);l.querySelector(".glideThumbItem")?.classList.add("active"),l.querySelectorAll("img").forEach(t=>{t.addEventListener("click",()=>{var e=t.closest(".glideThumbItem"),e=Array.from(l.querySelectorAll(".glideThumbItem")).indexOf(e);this.#setIndexGlideThumb(l,e),i.go("="+e)})}),i.on("run",()=>{this.#setIndexGlideThumb(l,i.index)})}}static#setIndexGlideThumb(e,t){var i=e.querySelectorAll(".glideThumbItem");e.querySelector(".glideThumbItem.active")?.classList.remove("active"),i[t]&&i[t].classList.add("active")}}